    palabras del texto y se agregan las que aparecen en esa coleccion. Asi una
    funcion de nombre normal nombrada en el encargo tambien se reconoce. La
    lista que vuelve no repite ningun nombre. Si `conocidas` es None o viene
    rara, se porta igual que antes.

    El texto se mira RENGLON POR RENGLON y cada renglon se clasifica como PROSA
    o como CODIGO PEGADO. Un renglon es de codigo cuando trae un parentesis de
    abrir precedido de letra, numero o raya baja, y ademas empieza con cuatro
    espacios o mas, o (ya sin espacios de la izquierda) empieza por return, def
    o class. En PROSA todo cuenta como antes. En CODIGO PEGADO una palabra de
    `conocidas` solo cuenta si la palabra anterior es funcion, funcion con
    tilde, def o class, o si la palabra trae un parentesis de abrir justo
    detras del nombre. Las palabras con raya baja se cuentan igual en ambos.
    """
    funciones = []

    def _es_codigo_pegado(renglon):
        pos = renglon.find("(")
        if pos <= 0:
            return False
        anterior = renglon[pos - 1]
        if not (anterior.isalnum() or anterior == "_"):
            return False
        sin_izq = renglon.lstrip()
        if len(renglon) - len(sin_izq) >= 4:
            return True
        for prefijo in ("return", "def", "class"):
            if sin_izq == prefijo or sin_izq.startswith(prefijo + " "):
                return True
        return False

    def _nombre_pegado_a_parentesis(palabra):
        corte = len(palabra)
        for _i, _c in enumerate(palabra):
            if not (_c.isalnum() or _c == "_"):
                corte = _i
                break
        if corte < len(palabra) and palabra[corte] == "(":
            return palabra[:corte]
        return None

    for renglon in texto_encargo.splitlines():
        es_codigo = _es_codigo_pegado(renglon)
        palabras = renglon.replace(",", " ").replace(";", " ").split()
        for indice, palabra in enumerate(palabras):
            limpia = palabra.strip("()[]{}<>\"'`.:")
            if limpia.startswith("_") and len(limpia) > 1:
                corte = len(limpia)
                for _i, _c in enumerate(limpia):
                    if not (_c.isalnum() or _c == "_"):
                        corte = _i
                        break
                nombre = limpia[:corte]
                # si despues de cortar no queda mas que la raya baja, no se exige
                if nombre.startswith("_") and len(nombre) > 1:
                    funciones.append(nombre)
        if not conocidas:
            continue
        try:
            for indice, palabra in enumerate(palabras):
                # una palabra con comillas es una etiqueta o texto pegado como
                # material, no una funcion que se vaya a tocar: no cuenta.
                if '"' in palabra or "'" in palabra or "`" in palabra:
                    continue
                limpia = palabra.strip("()[]{}<>\"'`.:")
                if limpia not in conocidas:
                    continue
                if not es_codigo:
                    if limpia not in funciones:
                        funciones.append(limpia)
                    continue
                anterior = palabras[indice - 1] if indice > 0 else ""
                anterior_limpia = anterior.strip("()[]{}<>\"'`.:")
                if anterior_limpia in ("funcion", "función", "def", "class"):
                    if limpia not in funciones:
                        funciones.append(limpia)
                    continue
                pegado = _nombre_pegado_a_parentesis(palabra)
                if pegado and pegado in conocidas and pegado not in funciones:
                    funciones.append(pegado)
        except Exception:
            pass
    return funciones

